def summary() -> dict[str, int]:
    """Counts by kind, danger and evidence, for the catalogue endpoints."""
    out: dict[str, int] = {"total": len(COMMANDS)}
    for c in COMMANDS.values():
        out[f"kind:{c.kind}"] = out.get(f"kind:{c.kind}", 0) + 1
        out[f"danger:{c.danger}"] = out.get(f"danger:{c.danger}", 0) + 1
        out[f"confidence:{c.confidence}"] = (
            out.get(f"confidence:{c.confidence}", 0) + 1)
    out["verified"] = len(VERIFIED_COMMANDS)
    return out
